"use client";
/* Toast, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Toast(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("toast"); }, []);
  return React.createElement("piix-sprite", { "name": "toast", ...piixAttrs(props) });
}

export default Toast;
